<tr data-kendala-id="{{ $k->id }}" data-search="{{ strtolower($k->perihal.' '.($k->tujuanSatuan->nama ?? '')) }}" data-prioritas="{{ $k->prioritas }}"><td>{{ $k->perihal }}</td><td style="text-align:center"><span class="satuan-pill">{{ $k->tujuanSatuan->kode ?? $k->tujuanSatuan->nama ?? '-' }}</span></td><td><span class="priority-tag prio-{{ strtolower($k->prioritas) }}">{{ $k->prioritas }}</span></td><td style="text-align:center"><span class="status-dot {{ in_array($k->status, ['Ditindaklanjuti','Selesai','Dikonfirmasi'], true) ? 'green' : ($k->status === 'Ditolak' ? 'bad' : 'amber') }}">{{ $k->status }}</span></td><td style="text-align:center">@if($k->tembusans->isEmpty())<span style="font-size:11px;color:var(--text-dim)">-</span>@else<div style="display:flex;flex-direction:column;gap:5px;align-items:center;text-align:center;max-width:220px;margin:0 auto">@foreach($k->tembusans as $t)<div style="font-size:11px;line-height:1.4"><span class="satuan-pill" style="font-size:10px">{{ $t->satuan->kode ?? $t->satuan->nama ?? '-' }}</span>@if($t->feedback)<div style="color:var(--success-bright);font-weight:700;margin-top:2px">Sudah dibalas</div>@else<div style="color:var(--text-dim);margin-top:2px;font-style:italic">Menunggu balasan…</div>@endif</div>@endforeach</div>@endif</td><td style="text-align:center">{{ $k->created_at->translatedFormat('d M Y H:i') }}</td><td><div class="review-actions" style="justify-content:center;flex-wrap:wrap"><button type="button" class="detail-btn" onclick="openReportDetail(this)" data-pengirim="{{ e($satuan->nama) }}" data-tujuan="{{ e($k->tujuanSatuan->nama ?? '-') }}" data-perihal="{{ e($k->perihal) }}" data-prioritas="{{ e($k->prioritas) }}" data-proyek="{{ e($k->kategori ?? '-') }}" data-tanggal="{{ e($k->created_at->translatedFormat('d M Y H:i')) }}" data-deskripsi="{{ e($k->deskripsi) }}" data-deskripsi-label="Isi Balasan" data-kendala="{{ e($k->catatan ?? '') }}" data-lampiran="{{ $k->lampiran_path ? collect([['url' => asset('storage/